import base64
import hashlib
import io
import json
import os
from pathlib import Path
import sys
import time
import urllib.request
import uuid
import zipfile

sys.path.insert(0, '/home/r/dev/minor/stackd/scripts/aws')
from aws_cli import run

ROOT = Path('/home/r/dev/minor/stackd')
OUT = ROOT / 'testdata/aws/stepfunctions/http_connections.json'
ACCOUNT = '000000000000'
REGION = 'us-west-2'
name = 'stackd-http-' + uuid.uuid4().hex[:10]
env = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_PAGER='', AWS_MAX_ATTEMPTS='1')
for k in list(env):
    if k.startswith('AWS_ENDPOINT_URL'):
        del env[k]
record = {'account': ACCOUNT, 'region': REGION, 'name': name, 'started_ms': int(time.time()*1000), 'observations': [], 'sources': [], 'source': Path(__file__).read_text(), 'transport_source': (ROOT/'scripts/aws/aws_cli.py').read_text(), 'value_provenance': 'All Basic passwords, API keys, OAuth client secrets, and OAuth tokens are synthetic inert probe values. Lambda URL NONE exposes only an ephemeral echo/token function; no real credentials are sent or returned.'}
prior = json.loads(OUT.read_text()) if OUT.exists() else None
if prior:
    record['earlier_attempt'] = prior

def save():
    OUT.write_text(json.dumps(record, indent=2) + '\n')

def obs(label, service, operation, params=None, strict=False):
    item = {'label': label, 'service': service, 'operation': operation, 'input': params or {}, 'request_started_ms': int(time.time()*1000)}
    p = run(service, operation, params or {}, env, options=['--cli-error-format','json','--cli-connect-timeout','10','--cli-read-timeout','90'], timeout=110)
    item['request_finished_ms'] = int(time.time()*1000)
    if p.returncode:
        try:
            err = json.loads(p.stderr)
        except json.JSONDecodeError:
            err = {'Code': 'CLIError', 'Message': p.stderr}
        item['result'] = {'code': err.get('Code','CLIError'), 'error': err}
    else:
        item['result'] = {'code': 'Success', 'output': json.loads(p.stdout) if p.stdout.strip() else {}}
    record['observations'].append(item)
    save()
    print(label, item['result']['code'], flush=True)
    if strict and item['result']['code'] != 'Success':
        raise RuntimeError(label + ': ' + json.dumps(item['result']))
    return item['result']

def ok(label, service, operation, params=None):
    return obs(label, service, operation, params, True)['output']

def policy(statements):
    return json.dumps({'Version':'2012-10-17','Statement':statements}, separators=(',',':'))

lambda_source = '''import base64
import json
import time

def handler(event, context):
    path = event.get('rawPath', '/')
    body = event.get('body', '')
    if event.get('isBase64Encoded'):
        body = base64.b64decode(body).decode('utf-8', errors='replace')
    echo = {'method': event['requestContext']['http']['method'], 'path': path, 'rawQueryString': event.get('rawQueryString', ''), 'headers': event.get('headers', {}), 'body': body}
    print(json.dumps({'owned_http_echo': echo}, separators=(',', ':')))
    headers = {'content-type': 'application/json', 'x-owned-response': 'echo-v1'}
    if path == '/oauth':
        response = {'access_token': 'owned-inert-oauth-token', 'token_type': 'Bearer', 'expires_in': 3600}
        print(json.dumps({'owned_oauth_response': response}))
        return {'statusCode': 200, 'headers': headers, 'body': json.dumps(response)}
    if path == '/text':
        return {'statusCode': 200, 'headers': {'content-type':'text/plain', 'x-owned-response':'plain-v1'}, 'body': 'owned plain response'}
    if path == '/binary':
        return {'statusCode': 200, 'headers': {'content-type':'application/octet-stream'}, 'body': 'owned inert bytes'}
    status = int(path.rsplit('/', 1)[1]) if path.startswith('/status/') else 200
    return {'statusCode': status, 'headers': headers, 'body': '' if status == 204 else json.dumps(echo, separators=(',', ':'))}
'''
record['lambda_source'] = lambda_source
roles = []
connections = []
secrets = []
function_created = False
log_created = False
machine_created = False
machine_arn = f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{name}'
log_group = '/aws/lambda/' + name
url = None

try:
    caller = ok('caller-identity','sts','get-caller-identity')
    if caller['Account'] != ACCOUNT:
        raise RuntimeError('Wrong native account')
    docs = [
        'https://docs.aws.amazon.com/step-functions/latest/dg/call-https-apis.html',
        'https://docs.aws.amazon.com/eventbridge/latest/APIReference/API_CreateConnectionOAuthRequestParameters.html',
        'https://docs.aws.amazon.com/lambda/latest/dg/urls-auth.html',
        'https://docs.aws.amazon.com/service-authorization/latest/reference/list_events.html'
    ]
    for doc in docs:
        with urllib.request.urlopen(doc, timeout=30) as response:
            raw = response.read()
            record['sources'].append({'url':doc,'effective_url':response.url,'retrieved_ms':int(time.time()*1000),'last_modified':response.headers.get('Last-Modified'),'etag':response.headers.get('ETag'),'sha256':hashlib.sha256(raw).hexdigest(),'source_html':raw.decode()})
        save()
    ok('create-log-group','logs','create-log-group',{'logGroupName':log_group})
    log_created = True
    lambda_role_name = name + '-lambda'
    trust = policy([{'Effect':'Allow','Principal':{'Service':'lambda.amazonaws.com'},'Action':'sts:AssumeRole'}])
    lr = ok('create-lambda-role','iam','create-role',{'RoleName':lambda_role_name,'AssumeRolePolicyDocument':trust})
    roles.append(lambda_role_name)
    ok('lambda-log-policy','iam','put-role-policy',{'RoleName':lambda_role_name,'PolicyName':'owned','PolicyDocument':policy([{'Effect':'Allow','Action':['logs:CreateLogStream','logs:PutLogEvents'],'Resource':f'arn:aws:logs:{REGION}:{ACCOUNT}:log-group:{log_group}:*'}])})
    time.sleep(12)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('index.py',lambda_source)
    cp = {'FunctionName':name,'Runtime':'python3.13','Role':lr['Role']['Arn'],'Handler':'index.handler','Timeout':10,'MemorySize':128,'Code':{'ZipFile':base64.b64encode(buf.getvalue()).decode()},'Description':'Short-lived inert owned HTTP and OAuth echo probe'}
    created = obs('create-function','lambda','create-function',cp)
    if created['code'] != 'Success':
        time.sleep(15)
        created = obs('create-function-retry','lambda','create-function',cp,True)
    function_created = True
    for attempt in range(30):
        cfg = ok('function-ready-'+str(attempt),'lambda','get-function-configuration',{'FunctionName':name})
        if cfg.get('State') == 'Active':
            break
        time.sleep(2)
    else:
        raise RuntimeError('Function never Active')
    ok('url-permission','lambda','add-permission',{'FunctionName':name,'StatementId':'OwnedURL','Action':'lambda:InvokeFunctionUrl','Principal':'*','FunctionUrlAuthType':'NONE'})
    ok('url-invoke-permission','lambda','add-permission',{'FunctionName':name,'StatementId':'OwnedURLInvoke','Action':'lambda:InvokeFunction','Principal':'*','InvokedViaFunctionUrl':True})
    url = ok('create-function-url','lambda','create-function-url-config',{'FunctionName':name,'AuthType':'NONE'})['FunctionUrl']
    record['endpoint'] = url
    save()
    params_by_kind = {
        'basic': {'AuthorizationType':'BASIC','AuthParameters':{'BasicAuthParameters':{'Username':'owned-user','Password':'owned-password'},'InvocationHttpParameters':{'HeaderParameters':[{'Key':'x-shared','Value':'connection-header'},{'Key':'x-secret','Value':'owned-inert-private-header','IsValueSecret':True}],'QueryStringParameters':[{'Key':'shared','Value':'connection query'},{'Key':'connectionOnly','Value':'query-only'}],'BodyParameters':[{'Key':'shared','Value':'connection-body'},{'Key':'connectionOnly','Value':'body-only'}]}}},
        'apikey': {'AuthorizationType':'API_KEY','AuthParameters':{'ApiKeyAuthParameters':{'ApiKeyName':'x-owned-api-key','ApiKeyValue':'owned-inert-api-key'}}},
        'oauth': {'AuthorizationType':'OAUTH_CLIENT_CREDENTIALS','AuthParameters':{'OAuthParameters':{'ClientParameters':{'ClientID':'owned-client','ClientSecret':'owned-client-secret'},'AuthorizationEndpoint':url+'oauth','HttpMethod':'POST','OAuthHttpParameters':{'HeaderParameters':[{'Key':'x-owned-oauth','Value':'token-request'}],'BodyParameters':[{'Key':'grant_type','Value':'client_credentials'},{'Key':'scope','Value':'owned-echo'}]}}}}
    }
    conn_arns = {}
    for kind, p in params_by_kind.items():
        cn = name + '-' + kind
        p = dict(Name=cn,Description='Owned inert HTTP task probe',**p)
        cr = ok('create-connection-'+kind,'events','create-connection',p)
        connections.append(cn)
        conn_arns[kind] = cr['ConnectionArn']
        for attempt in range(40):
            d = ok('connection-state-'+kind+'-'+str(attempt),'events','describe-connection',{'Name':cn})
            if d.get('SecretArn') and d['SecretArn'] not in secrets:
                secrets.append(d['SecretArn'])
            if d['ConnectionState'] == 'AUTHORIZED':
                break
            time.sleep(3)
        else:
            raise RuntimeError('Connection not AUTHORIZED: '+kind)
    statements = [
        {'Effect':'Allow','Action':'states:InvokeHTTPEndpoint','Resource':machine_arn,'Condition':{'StringLike':{'states:HTTPEndpoint':url+'*'},'StringEquals':{'states:HTTPMethod':['GET','POST','PUT','DELETE','PATCH','OPTIONS','HEAD']}}},
        {'Effect':'Allow','Action':'events:RetrieveConnectionCredentials','Resource':list(conn_arns.values())},
        {'Effect':'Allow','Action':'secretsmanager:GetSecretValue','Resource':secrets},
        {'Effect':'Allow','Action':'secretsmanager:DescribeSecret','Resource':secrets}
    ]
    role_arns = {}
    for variant in ['full','no-invoke','no-retrieve','no-get','no-describe']:
        rn = name + '-' + variant
        tr = policy([{'Effect':'Allow','Principal':{'Service':'states.amazonaws.com'},'Action':'sts:AssumeRole','Condition':{'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])
        rr = ok('create-role-'+variant,'iam','create-role',{'RoleName':rn,'AssumeRolePolicyDocument':tr})
        roles.append(rn)
        role_arns[variant] = rr['Role']['Arn']
        excluded = {'no-invoke':0,'no-retrieve':1,'no-get':2,'no-describe':3}.get(variant,-1)
        ok('policy-'+variant,'iam','put-role-policy',{'RoleName':rn,'PolicyName':'owned','PolicyDocument':policy([s for i,s in enumerate(statements) if i != excluded])})
    definition = {'StartAt':'CallOwnedHTTP','States':{'CallOwnedHTTP':{'Type':'Task','Resource':'arn:aws:states:::http:invoke','Parameters':{'ApiEndpoint.$':'$.endpoint','Method.$':'$.method','Authentication':{'ConnectionArn.$':'$.connection'},'Headers.$':'$.headers','QueryParameters.$':'$.query','RequestBody.$':'$.body','Transform.$':'$.transform'},'End':True}}}
    time.sleep(12)
    ok('create-express-machine','stepfunctions','create-state-machine',{'name':name,'definition':json.dumps(definition),'roleArn':role_arns['full'],'type':'EXPRESS'})
    machine_created = True
    time.sleep(5)
    def execute(label, kind='apikey', method='POST', path='echo', headers=None, query=None, body=None, transform=None):
        inp = {'endpoint':url+path,'method':method,'connection':conn_arns[kind],'headers':headers or {},'query':query or {},'body':{} if body is None else body,'transform':transform or {'RequestBodyEncoding':'NONE'}}
        res = ok(label,'stepfunctions','start-sync-execution',{'stateMachineArn':machine_arn,'name':label+'-'+uuid.uuid4().hex[:6],'input':json.dumps(inp)})
        if res.get('output'):
            record.setdefault('decoded_outputs',{})[label] = json.loads(res['output'])
        save()
        return res
    control = execute('basic-merge-json','basic',headers={'X-Shared':'task-case-header','x-shared':'task-header','x-task-only':'task-only','content-type':'application/json'},query={'shared':'task query','taskOnly':'a+b & c'},body={'shared':{'nested':'task-body'},'taskOnly':[1,'two'],'nested':{'a':'b'}})
    if control.get('status') != 'SUCCEEDED':
        time.sleep(20)
        control = execute('basic-merge-json-retry','basic',headers={'x-shared':'task-header','x-task-only':'task-only','content-type':'application/json'},query={'shared':'task query','taskOnly':'a+b & c'},body={'shared':{'nested':'task-body'},'taskOnly':[1,'two'],'nested':{'a':'b'}})
    if control.get('status') != 'SUCCEEDED':
        raise RuntimeError('Working control failed: '+json.dumps(control))
    execute('apikey-json','apikey',body={'owned':'api-key-body'})
    execute('oauth-json','oauth',body={'owned':'oauth-body'})
    for style in ['INDICES','REPEAT','COMMAS','BRACKETS']:
        execute('form-'+style.lower(),'basic',headers={'content-type':'application/x-www-form-urlencoded'},body={'shared':'task-body','items':['red green','blue+gold'],'nested':{'enabled':True,'count':2}},transform={'RequestBodyEncoding':'URL_ENCODED','RequestEncodingOptions':{'ArrayFormat':style}})
    execute('string-body-no-merge','apikey',headers={'content-type':'text/plain'},body='owned raw string')
    execute('string-body-connection-merge-error','basic',body='owned raw string')
    execute('prohibited-task-authorization-header','apikey',headers={'Authorization':'owned-inert-forbidden'})
    execute('method-get-json','apikey',method='GET',query={'owned':'get query'})
    execute('method-head','apikey',method='HEAD')
    execute('status-204','apikey',method='DELETE',path='status/204')
    execute('status-418','apikey',method='PATCH',path='status/418',body={'owned':'status error'})
    execute('response-plain-text','apikey',method='GET',path='text')
    execute('response-unsupported-content-type','apikey',method='GET',path='binary')
    for variant in ['no-invoke','no-retrieve','no-get','no-describe']:
        ok('switch-role-'+variant,'stepfunctions','update-state-machine',{'stateMachineArn':machine_arn,'roleArn':role_arns[variant]})
        time.sleep(12)
        execute('iam-'+variant,'apikey',body={'owned':variant})
    ok('restore-full-role','stepfunctions','update-state-machine',{'stateMachineArn':machine_arn,'roleArn':role_arns['full']})
    time.sleep(12)
    execute('iam-restored-working-control','apikey',body={'owned':'restored-full-policy'})
    ok('echo-log-evidence','logs','filter-log-events',{'logGroupName':log_group})
    record['capture_completed'] = True
except Exception as exc:
    record['failure'] = str(exc)
    save()
    print('FAILURE', str(exc), flush=True)
finally:
    if machine_created:
        obs('cleanup-delete-machine','stepfunctions','delete-state-machine',{'stateMachineArn':machine_arn})
    for cn in connections:
        d = obs('cleanup-describe-connection-'+cn,'events','describe-connection',{'Name':cn})
        if d['code'] == 'Success' and d['output'].get('SecretArn') not in secrets:
            secrets.append(d['output']['SecretArn'])
        obs('cleanup-delete-connection-'+cn,'events','delete-connection',{'Name':cn})
    if function_created:
        obs('cleanup-final-echo-logs','logs','filter-log-events',{'logGroupName':log_group})
        obs('cleanup-delete-url','lambda','delete-function-url-config',{'FunctionName':name})
        for sid in ['OwnedURL','OwnedURLInvoke']:
            obs('cleanup-remove-'+sid,'lambda','remove-permission',{'FunctionName':name,'StatementId':sid})
        obs('cleanup-delete-function','lambda','delete-function',{'FunctionName':name})
    if log_created:
        obs('cleanup-delete-log-group','logs','delete-log-group',{'logGroupName':log_group})
    for rn in roles:
        obs('cleanup-delete-policy-'+rn,'iam','delete-role-policy',{'RoleName':rn,'PolicyName':'owned'})
        obs('cleanup-delete-role-'+rn,'iam','delete-role',{'RoleName':rn})
    absent = {}
    if machine_created:
        for attempt in range(40):
            r = obs('verify-machine-absent-'+str(attempt),'stepfunctions','describe-state-machine',{'stateMachineArn':machine_arn})
            if r['code'] == 'StateMachineDoesNotExist':
                break
            time.sleep(3)
        absent['machine'] = r['code'] == 'StateMachineDoesNotExist'
    for cn in connections:
        r = obs('verify-connection-absent-'+cn,'events','describe-connection',{'Name':cn})
        absent[cn] = r['code'] == 'ResourceNotFoundException'
    for arn in secrets:
        for attempt in range(30):
            r = obs('verify-secret-absent-'+arn.rsplit('/',1)[-1]+'-'+str(attempt),'secretsmanager','describe-secret',{'SecretId':arn})
            if r['code'] == 'ResourceNotFoundException':
                break
            time.sleep(3)
        absent[arn] = r['code'] == 'ResourceNotFoundException'
    listing = obs('verify-no-secret-incarnations','secretsmanager','list-secrets',{'IncludePlannedDeletion':True,'Filters':[{'Key':'name','Values':['events!connection/'+name]}]})
    absent['all-secret-incarnations'] = listing['code'] == 'Success' and not listing['output'].get('SecretList')
    if function_created:
        r = obs('verify-function-absent','lambda','get-function-configuration',{'FunctionName':name})
        absent['function'] = r['code'] == 'ResourceNotFoundException'
        r = obs('verify-url-absent','lambda','get-function-url-config',{'FunctionName':name})
        absent['url'] = r['code'] == 'ResourceNotFoundException'
    if log_created:
        r = obs('verify-log-group-absent','logs','describe-log-groups',{'logGroupNamePrefix':log_group})
        absent['log-group'] = r['code'] == 'Success' and not r['output'].get('logGroups')
    for rn in roles:
        r = obs('verify-role-absent-'+rn,'iam','get-role',{'RoleName':rn})
        absent[rn] = r['code'] == 'NoSuchEntity'
    record['cleanup_absence'] = absent
    record['cleanup_complete'] = all(absent.values())
    record['finished_ms'] = int(time.time()*1000)
    save()
    print('FINISHED', record.get('capture_completed'), record['cleanup_complete'], str(OUT), flush=True)

