import base64
import hashlib
import io
import json
import os
from pathlib import Path
import sys
import time
import urllib.request
import uuid
import zipfile

sys.path.insert(0, '/home/r/dev/minor/stackd/scripts/aws')
from aws_cli import run

ROOT = Path('/home/r/dev/minor/stackd')
OUT = ROOT / 'testdata/aws/stepfunctions/http_connections.json'
ACCOUNT = '000000000000'
REGION = 'us-west-2'
name = 'stackd-http-' + uuid.uuid4().hex[:10]
env = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_PAGER='', AWS_MAX_ATTEMPTS='1')
for k in list(env):
    if k.startswith('AWS_ENDPOINT_URL'):
        del env[k]
record = {'account': ACCOUNT, 'region': REGION, 'name': name, 'started_ms': int(time.time()*1000), 'observations': [], 'sources': [], 'source': Path(__file__).read_text(), 'transport_source': (ROOT/'scripts/aws/aws_cli.py').read_text(), 'value_provenance': 'All Basic passwords, API keys, OAuth client secrets, and OAuth tokens are synthetic inert probe values. Lambda URL NONE exposes only an ephemeral echo/token function; no real credentials are sent or returned.'}
prior = json.loads(OUT.read_text()) if OUT.exists() else None
if prior:
    record['earlier_attempt'] = prior

def save():
    OUT.write_text(json.dumps(record, indent=2) + '\n')

def obs(label, service, operation, params=None, strict=False):
    item = {'label': label, 'service': service, 'operation': operation, 'input': params or {}, 'request_started_ms': int(time.time()*1000)}
    p = run(service, operation, params or {}, env, options=['--cli-error-format','json','--cli-connect-timeout','10','--cli-read-timeout','90'], timeout=110)
    item['request_finished_ms'] = int(time.time()*1000)
    if p.returncode:
        try:
            err = json.loads(p.stderr)
        except json.JSONDecodeError:
            err = {'Code': 'CLIError', 'Message': p.stderr}
        item['result'] = {'code': err.get('Code','CLIError'), 'error': err}
    else:
        item['result'] = {'code': 'Success', 'output': json.loads(p.stdout) if p.stdout.strip() else {}}
    record['observations'].append(item)
    save()
    print(label, item['result']['code'], flush=True)
    if strict and item['result']['code'] != 'Success':
        raise RuntimeError(label + ': ' + json.dumps(item['result']))
    return item['result']

def ok(label, service, operation, params=None):
