    save()
    print(label, item['result']['code'], flush=True)
    if strict and item['result']['code'] != 'Success':
        raise RuntimeError(label + ': ' + json.dumps(item['result']))
    return item['result']

def ok(label, service, operation, params=None):
    return obs(label, service, operation, params, True)['output']

def policy(statements):
    return json.dumps({'Version':'2012-10-17','Statement':statements}, separators=(',',':'))

