        'https://docs.aws.amazon.com/eventbridge/latest/APIReference/API_CreateConnectionOAuthRequestParameters.html',
        'https://docs.aws.amazon.com/lambda/latest/dg/urls-auth.html',
        'https://docs.aws.amazon.com/service-authorization/latest/reference/list_events.html'
    ]
    for doc in docs:
        with urllib.request.urlopen(doc, timeout=30) as response:
            raw = response.read()
            record['sources'].append({'url':doc,'effective_url':response.url,'retrieved_ms':int(time.time()*1000),'last_modified':response.headers.get('Last-Modified'),'etag':response.headers.get('ETag'),'sha256':hashlib.sha256(raw).hexdigest(),'source_html':raw.decode()})
        save()
    ok('create-log-group','logs','create-log-group',{'logGroupName':log_group})
    log_created = True
    lambda_role_name = name + '-lambda'
    trust = policy([{'Effect':'Allow','Principal':{'Service':'lambda.amazonaws.com'},'Action':'sts:AssumeRole'}])
    lr = ok('create-lambda-role','iam','create-role',{'RoleName':lambda_role_name,'AssumeRolePolicyDocument':trust})
    roles.append(lambda_role_name)
    ok('lambda-log-policy','iam','put-role-policy',{'RoleName':lambda_role_name,'PolicyName':'owned','PolicyDocument':policy([{'Effect':'Allow','Action':['logs:CreateLogStream','logs:PutLogEvents'],'Resource':f'arn:aws:logs:{REGION}:{ACCOUNT}:log-group:{log_group}:*'}])})
    time.sleep(12)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('index.py',lambda_source)
    cp = {'FunctionName':name,'Runtime':'python3.13','Role':lr['Role']['Arn'],'Handler':'index.handler','Timeout':10,'MemorySize':128,'Code':{'ZipFile':base64.b64encode(buf.getvalue()).decode()},'Description':'Short-lived inert owned HTTP and OAuth echo probe'}
    created = obs('create-function','lambda','create-function',cp)
    if created['code'] != 'Success':
        time.sleep(15)
        created = obs('create-function-retry','lambda','create-function',cp,True)
    function_created = True
    for attempt in range(30):
        cfg = ok('function-ready-'+str(attempt),'lambda','get-function-configuration',{'FunctionName':name})
        if cfg.get('State') == 'Active':
            break
        time.sleep(2)
    else:
        raise RuntimeError('Function never Active')
    ok('url-permission','lambda','add-permission',{'FunctionName':name,'StatementId':'OwnedURL','Action':'lambda:InvokeFunctionUrl','Principal':'*','FunctionUrlAuthType':'NONE'})
    ok('url-invoke-permission','lambda','add-permission',{'FunctionName':name,'StatementId':'OwnedURLInvoke','Action':'lambda:InvokeFunction','Principal':'*','InvokedViaFunctionUrl':True})
    url = ok('create-function-url','lambda','create-function-url-config',{'FunctionName':name,'AuthType':'NONE'})['FunctionUrl']
    record['endpoint'] = url
    save()
    params_by_kind = {kind: {'AuthorizationType':'API_KEY','AuthParameters':{'ApiKeyAuthParameters':{'ApiKeyName':'x-owned-api-key','ApiKeyValue':'owned-inert-'+kind}}} for kind in ['apikey','noretrieve','denyretrieve','noget','nodescribe']}
    conn_arns = {}
    secret_arns = {}
    for kind, p in params_by_kind.items():
        cn = name + '-' + kind
        p = dict(Name=cn,Description='Owned inert HTTP task probe',**p)
        cr = ok('create-connection-'+kind,'events','create-connection',p)
        connections.append(cn)
        conn_arns[kind] = cr['ConnectionArn']
        for attempt in range(40):
            d = ok('connection-state-'+kind+'-'+str(attempt),'events','describe-connection',{'Name':cn})
            if d.get('SecretArn') and d['SecretArn'] not in secrets:
                secrets.append(d['SecretArn'])
                secret_arns[kind] = d['SecretArn']
            if d['ConnectionState'] == 'AUTHORIZED':
                break
            time.sleep(3)
        else:
            raise RuntimeError('Connection not AUTHORIZED: '+kind)
    statements = [
        {'Effect':'Allow','Action':'states:InvokeHTTPEndpoint','Resource':machine_arn,'Condition':{'StringEquals':{'states:HTTPEndpoint':url+'echo','states:HTTPMethod':['GET','POST','HEAD']}}},
        {'Effect':'Allow','Action':'events:RetrieveConnectionCredentials','Resource':[arn for kind,arn in conn_arns.items() if kind != 'noretrieve']},
        {'Effect':'Deny','Action':'events:RetrieveConnectionCredentials','Resource':conn_arns['denyretrieve']},
        {'Effect':'Allow','Action':'secretsmanager:GetSecretValue','Resource':[arn for kind,arn in secret_arns.items() if kind != 'noget']},
        {'Effect':'Allow','Action':'secretsmanager:DescribeSecret','Resource':[arn for kind,arn in secret_arns.items() if kind != 'nodescribe']}
    ]
    role_arns = {}
    for variant in ['full']:
        rn = name + '-' + variant
        tr = policy([{'Effect':'Allow','Principal':{'Service':'states.amazonaws.com'},'Action':'sts:AssumeRole','Condition':{'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])
        rr = ok('create-role-'+variant,'iam','create-role',{'RoleName':rn,'AssumeRolePolicyDocument':tr})
        roles.append(rn)
        role_arns[variant] = rr['Role']['Arn']
        ok('policy-'+variant,'iam','put-role-policy',{'RoleName':rn,'PolicyName':'owned','PolicyDocument':policy(statements)})
    parameters = {'ApiEndpoint.$':'$.endpoint','Method.$':'$.method','Authentication':{'ConnectionArn.$':'$.connection'},'Headers.$':'$.headers','QueryParameters.$':'$.query','RequestBody.$':'$.body','Transform.$':'$.transform'}
    without_body = {key:value for key,value in parameters.items() if key != 'RequestBody.$'}
    definition = {'StartAt':'ChooseBody','States':{'ChooseBody':{'Type':'Choice','Choices':[{'Variable':'$.method','StringEquals':'HEAD','Next':'WithoutBody'}],'Default':'WithBody'},'WithBody':{'Type':'Task','Resource':'arn:aws:states:::http:invoke','Parameters':parameters,'End':True},'WithoutBody':{'Type':'Task','Resource':'arn:aws:states:::http:invoke','Parameters':without_body,'End':True}}}
    time.sleep(20)
    ok('create-express-machine','stepfunctions','create-state-machine',{'name':name,'definition':json.dumps(definition),'roleArn':role_arns['full'],'type':'EXPRESS'})
    machine_created = True
    time.sleep(5)
    def execute(label, kind='apikey', method='POST', path='echo', headers=None, query=None, body=None, transform=None):
        inp = {'endpoint':url+path,'method':method,'connection':conn_arns[kind],'headers':headers or {},'query':query or {},'body':{} if body is None else body,'transform':transform or {'RequestBodyEncoding':'NONE'}}
        res = ok(label,'stepfunctions','start-sync-execution',{'stateMachineArn':machine_arn,'name':label+'-'+uuid.uuid4().hex[:6],'input':json.dumps(inp)})
        if res.get('output'):
            record.setdefault('decoded_outputs',{})[label] = json.loads(res['output'])
        save()
        return res
    first = execute('fixed-role-working-control-before',body={'owned':'full-before'})
    if first.get('status') != 'SUCCEEDED':
        raise RuntimeError('Initial fixed-role control failed: '+json.dumps(first))
    for kind in ['noretrieve','denyretrieve','noget','nodescribe']:
        r = execute('fixed-role-missing-'+kind,kind,body={'owned':kind})
        if r.get('error') != 'Events.ConnectionResource.AccessDenied':
            raise RuntimeError('Expected scoped dependency denial for '+kind+': '+json.dumps(r))
    r = execute('fixed-role-no-invoke',path='denied-echo',body={'owned':'no-invoke'})
    if r.get('error') != 'States.Http.AccessDenied':
        raise RuntimeError('Expected endpoint permission denial: '+json.dumps(r))
    for label, method in [('fixed-role-head-no-body','HEAD'),('fixed-role-get-control','GET'),('fixed-role-working-control-after','POST')]:
        r = execute(label,method=method,body={'owned':label})
        if r.get('status') != 'SUCCEEDED':
            raise RuntimeError('Fixed-role control failed: '+json.dumps(r))
    ok('echo-log-evidence','logs','filter-log-events',{'logGroupName':log_group})
    record['capture_completed'] = True
except Exception as exc:
    record['failure'] = str(exc)
    save()
    print('FAILURE', str(exc), flush=True)
finally:
    if machine_created:
        obs('cleanup-delete-machine','stepfunctions','delete-state-machine',{'stateMachineArn':machine_arn})
    for cn in connections:
        d = obs('cleanup-describe-connection-'+cn,'events','describe-connection',{'Name':cn})
        if d['code'] == 'Success' and d['output'].get('SecretArn') not in secrets:
            secrets.append(d['output']['SecretArn'])
        obs('cleanup-delete-connection-'+cn,'events','delete-connection',{'Name':cn})
    if function_created:
        obs('cleanup-final-echo-logs','logs','filter-log-events',{'logGroupName':log_group})
        obs('cleanup-delete-url','lambda','delete-function-url-config',{'FunctionName':name})
        for sid in ['OwnedURL','OwnedURLInvoke']:
            obs('cleanup-remove-'+sid,'lambda','remove-permission',{'FunctionName':name,'StatementId':sid})
        obs('cleanup-delete-function','lambda','delete-function',{'FunctionName':name})
    if log_created:
        obs('cleanup-delete-log-group','logs','delete-log-group',{'logGroupName':log_group})
    for rn in roles:
        obs('cleanup-delete-policy-'+rn,'iam','delete-role-policy',{'RoleName':rn,'PolicyName':'owned'})
        obs('cleanup-delete-role-'+rn,'iam','delete-role',{'RoleName':rn})
    absent = {}
    if machine_created:
        for attempt in range(40):
            r = obs('verify-machine-absent-'+str(attempt),'stepfunctions','describe-state-machine',{'stateMachineArn':machine_arn})
            if r['code'] == 'StateMachineDoesNotExist':
                break
            time.sleep(3)
        absent['machine'] = r['code'] == 'StateMachineDoesNotExist'
    for cn in connections:
        r = obs('verify-connection-absent-'+cn,'events','describe-connection',{'Name':cn})
        absent[cn] = r['code'] == 'ResourceNotFoundException'
    for arn in secrets:
        for attempt in range(30):
            r = obs('verify-secret-absent-'+arn.rsplit('/',1)[-1]+'-'+str(attempt),'secretsmanager','describe-secret',{'SecretId':arn})
            if r['code'] == 'ResourceNotFoundException':
                break
            time.sleep(3)
        absent[arn] = r['code'] == 'ResourceNotFoundException'
    listing = obs('verify-no-secret-incarnations','secretsmanager','list-secrets',{'IncludePlannedDeletion':True,'Filters':[{'Key':'name','Values':['events!connection/'+name]}]})
    absent['all-secret-incarnations'] = listing['code'] == 'Success' and not listing['output'].get('SecretList')
    if function_created:
        r = obs('verify-function-absent','lambda','get-function-configuration',{'FunctionName':name})
        absent['function'] = r['code'] == 'ResourceNotFoundException'
        r = obs('verify-url-absent','lambda','get-function-url-config',{'FunctionName':name})
        absent['url'] = r['code'] == 'ResourceNotFoundException'
    if log_created:
        r = obs('verify-log-group-absent','logs','describe-log-groups',{'logGroupNamePrefix':log_group})
        absent['log-group'] = r['code'] == 'Success' and not r['output'].get('logGroups')
    for rn in roles:
        r = obs('verify-role-absent-'+rn,'iam','get-role',{'RoleName':rn})
        absent[rn] = r['code'] == 'NoSuchEntity'
    record['cleanup_absence'] = absent
    record['cleanup_complete'] = all(absent.values())
    record['finished_ms'] = int(time.time()*1000)
    save()
    print('FINISHED', record.get('capture_completed'), record['cleanup_complete'], str(OUT), flush=True)

followup_attempts.transport_source:
"""AWS CLI transport shared by native behavior probes.

Callers own endpoint/retry choices, observations and resource cleanup. JSON shapes
remain open because probes deliberately exercise invalid and newly added inputs.
"""
import ast
import json
import re
import subprocess
from collections.abc import Mapping, Sequence
from typing import Any, NotRequired, TypedDict


class ProbeResult(TypedDict):
    code: str
    output: NotRequired[dict[str, Any]]
    error: NotRequired[dict[str, Any]]
    message: NotRequired[str]
    http_status: NotRequired[int]


class CLITimeout(RuntimeError):
    """A bounded CLI call expired; command arguments may contain secrets."""


class AWSCLIError(RuntimeError):
    """A failed strict call, retaining native JSON error fields for its caller."""

    def __init__(self, service: str, operation: str, stderr: str, details: dict[str, Any]):
        super().__init__(f"{service}:{operation}: {stderr.strip()}")
        self.details = details


def run(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
        env: Mapping[str, str] | None = None, *, options: Sequence[str] = (),
        timeout: float | None = None) -> subprocess.CompletedProcess[str]:
    """Execute one CLI command without interpreting service or client failures."""
    command = ["aws", service, operation, "--output", "json", "--no-cli-pager"]
    if parameters is not None:
        command += ["--cli-input-json", json.dumps(parameters)]
    try:
        return subprocess.run(command + list(options), env=env, capture_output=True,
                              text=True, check=False, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise CLITimeout("AWS CLI timed out during " + operation) from None


def call(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
         env: Mapping[str, str] | None = None, *, paginate: bool = True,
         error_format: str | None = None) -> dict[str, Any]:
    """Return JSON output; service and CLI-validation errors retain typed details.

    Configuration and transport failures abort capture instead of becoming
    observations of AWS behavior. AWS CLI uses 252 for input errors and 254
    for service errors.
    """
    options = ["--cli-connect-timeout", "10", "--cli-read-timeout", "30"]
    if error_format is not None:
        options += ["--cli-error-format", error_format]
    if not paginate:
        options.append("--no-paginate")
    process = run(service, operation, parameters or None, env, options=options)
    if process.returncode:
        diagnosis = f"{service}:{operation}: {process.stderr.strip()}"
        if error_format == "json" and process.returncode in (252, 254):
            try:
                details = json.loads(process.stderr)
            except json.JSONDecodeError:
                raise RuntimeError(diagnosis) from None
            if isinstance(details, dict) and isinstance(details.get("Code"), str):
                raise AWSCLIError(service, operation, process.stderr, details)
        raise RuntimeError(diagnosis)
    return result(process)["output"]


def observe(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
            env: Mapping[str, str] | None = None, *, paginate: bool = True) -> ProbeResult:
    """Capture native JSON success/error fields; callers own output redaction."""
    try:
        output = call(service, operation, parameters, env, paginate=paginate, error_format="json")
    except AWSCLIError as error:
        return {"code": error.details["Code"], "error": error.details}
    return {"code": "Success", "output": output}


def _text_error(stderr: str) -> tuple[str, str | None]:
    match = re.search(r"An error occurred \(([^)]+)\)(?:.*?operation(?: \([^)]*\))?: (.*))?", stderr)
    return (match[1], match[2]) if match else ("CLIError", None)


def result(process: subprocess.CompletedProcess[str], *, cli_error: str = "CLIError",
           cli_message: str | None = "AWS CLI failed; raw diagnostics discarded",
           debug: bool = False) -> ProbeResult:
    """Decode an observation, separating modeled errors from CLI rejection.

    A None client message retains the final three diagnostic lines for probes
    whose captured CLI-validation observations include those lines.
    """
    if process.returncode:
        code, message = _text_error(process.stderr)
        decoded: ProbeResult = {
            "code": code if message is not None else cli_error,
            "message": message if message is not None else cli_message if cli_message is not None
            else " ".join(process.stderr.splitlines()[-3:]),
        }
    else:
        decoded = {"code": "Success", "output": json.loads(process.stdout) if process.stdout.strip() else {}}
    if debug:
        statuses = re.findall(r'"[A-Z]+ [^"\r\n]* HTTP/1\.[01]" (\d{3})', process.stderr)
        if statuses:
            decoded["http_status"] = int(statuses[-1])
    return decoded


def error_code(process: subprocess.CompletedProcess[str]) -> str:
    """Decode code-only observations, including CLI ParamValidation errors."""
    return _text_error(process.stderr)[0]


def raw_xml(process: subprocess.CompletedProcess[str]) -> bytes | None:
    """Extract the last XML response from CLI debug output; discard other logs."""
    raw = None
    for line in process.stderr.splitlines():
        if line.startswith(("b'<", 'b"<')):
            try:
                candidate = ast.literal_eval(line)
                if candidate.startswith(b"<"):
                    raw = candidate
            except (ValueError, SyntaxError):
                pass
    return raw

followup_attempts.lambda_source:
import base64
import json
import time

def handler(event, context):
    path = event.get('rawPath', '/')
    body = event.get('body', '')
    if event.get('isBase64Encoded'):
        body = base64.b64decode(body).decode('utf-8', errors='replace')
    echo = {'method': event['requestContext']['http']['method'], 'path': path, 'rawQueryString': event.get('rawQueryString', ''), 'headers': event.get('headers', {}), 'body': body}
    print(json.dumps({'owned_http_echo': echo}, separators=(',', ':')))
    headers = {'content-type': 'application/json', 'x-owned-response': 'echo-v1'}
    if path == '/oauth':
        response = {'access_token': 'owned-inert-oauth-token', 'token_type': 'Bearer', 'expires_in': 3600}
        print(json.dumps({'owned_oauth_response': response}))
        return {'statusCode': 200, 'headers': headers, 'body': json.dumps(response)}
    if path == '/text':
        return {'statusCode': 200, 'headers': {'content-type':'text/plain', 'x-owned-response':'plain-v1'}, 'body': 'owned plain response'}
    if path == '/binary':
        return {'statusCode': 200, 'headers': {'content-type':'application/octet-stream'}, 'body': 'owned inert bytes'}
    status = int(path.rsplit('/', 1)[1]) if path.startswith('/status/') else 200
    return {'statusCode': status, 'headers': headers, 'body': '' if status == 204 else json.dumps(echo, separators=(',', ':'))}
